#!/usr/bin/env python3
"""
detect_text_layer.py — born-digital vs scanned-image probe for PDF pages.

Why PyMuPDF (fitz) over pdftotext:
  - PyMuPDF gives per-page text extraction as a first-class scriptable API
    (page.get_text()) with no extra process/parsing needed beyond the one
    `python3 detect_text_layer.py` subprocess already required by the
    "bundled scripts run from filesystem, not MCP" convention.
  - Its extraction quality is a decent born-digital signal on its own: a
    page with a real text layer returns dense, coherent text; a scanned
    image-only page returns empty or near-empty text (PyMuPDF does not OCR).
  - pdftotext (poppler-utils) is a viable FALLBACK if PyMuPDF isn't
    installed in a given environment — it gives similar per-page text via
    `pdftotext -f N -l N file.pdf -` — but we don't implement a dual-path
    here; PyMuPDF is preferred as the primary because it's one dependency
    (`pip install pymupdf`) instead of a shelled-out poppler binary, and
    returns page count / metadata in the same call.

Threshold reasoning:
  DENSITY_THRESHOLD_CHARS = 20 non-whitespace characters per page.
  A born-digital page of running academic prose has hundreds to thousands
  of chars. A scanned page with NO text layer returns 0 chars. The
  interesting middle ground is a scanned page that has a *thin* OCR'd text
  layer already baked in by a prior batch scan (e.g. just a running header
  or page number was OCR'd, not the body) — that could produce a handful of
  characters without being usably born-digital. >20 chars is high enough to
  reject "just a header/page number leaked through" false positives, but low
  enough not to reject genuinely sparse pages (e.g. a title page, a mostly-
  blank divider page) that ARE fully born-digital and shouldn't be re-OCR'd
  unnecessarily. This is a heuristic, not a guarantee — tune per-corpus if a
  particular document class misclassifies.

Usage:
  python3 detect_text_layer.py <path/to/file.pdf> [--pages "1-20" | "5,7,9-12"]

Output (stdout, JSON):
  {
    "document_path": "...",
    "total_pages": 42,
    "density_threshold_chars": 20,
    "pages": [
      {"page_number": 1, "is_born_digital": true, "char_count": 812, "text": "..."},
      {"page_number": 2, "is_born_digital": false, "char_count": 0, "text": ""},
      ...
    ]
  }

On error: prints {"error": "<actionable message>"} to stdout and exits 1.
Never leaves temp files (this script does no rasterization — that's
rasterize_pages.py's job).
"""

import argparse
import json
import sys

DENSITY_THRESHOLD_CHARS = 20


def parse_page_spec(spec: str, total_pages: int) -> list[int]:
    """Parse '1-20' or '5,7,9-12' into a sorted, deduped, 1-based page list."""
    pages: set[int] = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue
        if "-" in part:
            start_s, end_s = part.split("-", 1)
            start, end = int(start_s), int(end_s)
            if start < 1 or end < start:
                raise ValueError(f'malformed page range segment "{part}"')
            if end > total_pages:
                raise ValueError(
                    f'page range segment "{part}" exceeds document length ({total_pages} pages)'
                )
            pages.update(range(start, end + 1))
        else:
            p = int(part)
            if p < 1 or p > total_pages:
                raise ValueError(
                    f"page {p} out of range (document has {total_pages} pages)"
                )
            pages.add(p)
    return sorted(pages)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("document_path")
    ap.add_argument(
        "--pages", default=None, help='e.g. "1-20" or "5,7,9-12"; default: all pages'
    )
    ap.add_argument(
        "--threshold",
        type=int,
        default=DENSITY_THRESHOLD_CHARS,
        help="non-whitespace char count above which a page counts as born-digital",
    )
    args = ap.parse_args()

    try:
        import fitz  # PyMuPDF
    except ImportError:
        print(
            json.dumps(
                {
                    "error": (
                        "PyMuPDF is not installed. Run `pip install pymupdf` (or use the "
                        "pdftotext fallback documented in this script's header) before "
                        "calling gemini_ocr."
                    )
                }
            )
        )
        return 1

    try:
        doc = fitz.open(args.document_path)
    except Exception as e:  # noqa: BLE001 - surface any open failure as actionable JSON
        print(
            json.dumps(
                {
                    "error": f"document_path does not exist or is not a readable PDF: {args.document_path} ({e})"
                }
            )
        )
        return 1

    total_pages = doc.page_count
    try:
        page_numbers = (
            parse_page_spec(args.pages, total_pages)
            if args.pages
            else list(range(1, total_pages + 1))
        )
    except ValueError as e:
        print(json.dumps({"error": f"invalid --pages value: {e}"}))
        return 1

    results = []
    for page_number in page_numbers:
        page = doc.load_page(page_number - 1)  # fitz is 0-based
        text = page.get_text("text")
        char_count = len("".join(text.split()))  # non-whitespace char count
        results.append(
            {
                "page_number": page_number,
                "is_born_digital": char_count > args.threshold,
                "char_count": char_count,
                "text": text,
            }
        )

    print(
        json.dumps(
            {
                "document_path": args.document_path,
                "total_pages": total_pages,
                "density_threshold_chars": args.threshold,
                "pages": results,
            },
            ensure_ascii=False,
        )
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
